/* Read-only attendance reports. Uses only the server-scoped workspace already in memory. */
(function(root){
'use strict';
const ZONE='Africa/Cairo', id=v=>String(v), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayFmt=new Intl.DateTimeFormat('en-CA',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit'});
function day(v){const d=new Date(v);if(!Number.isFinite(+d))return '';const p=Object.fromEntries(dayFmt.formatToParts(d).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`;}
function stamp(v){if(!v||!Number.isFinite(+new Date(v)))return '—';return new Intl.DateTimeFormat('en-GB',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZoneName:'shortOffset'}).format(new Date(v));}
const hours=n=>(n/36e5).toFixed(2), duration=p=>p.out&&Number.isFinite(Date.parse(p.in))&&Number.isFinite(Date.parse(p.out))&&Date.parse(p.out)>Date.parse(p.in)?Date.parse(p.out)-Date.parse(p.in):0;
function closeKind(p){if(!p.out)return 'open';if(['auto','employee','admin'].includes(p.closeSource))return p.closeSource;if(p.autoClosed==='shift_cap'||p.autoClosed==='day_cap'||p.autoClosePolicy==='owner-caps-20261028-8.5h'||p.outLocation?.auto===true)return 'auto';return 'unknown';}
function closeLabel(p){switch(closeKind(p)){case 'open':return 'وردية مفتوحة';case 'auto':return 'إغلاق تلقائي عند الحد';case 'employee':return 'انصراف مسجل بواسطة الموظف';case 'admin':return 'إغلاق إداري بواسطة المالك';default:return 'مصدر الإغلاق غير موثق';}}
function unionMs(rows){const spans=rows.filter(p=>duration(p)>0).map(p=>[Date.parse(p.in),Date.parse(p.out)]).sort((a,b)=>a[0]-b[0]);let total=0,start=null,end=null;for(const [a,b]of spans){if(start===null){start=a;end=b;}else if(a<=end)end=Math.max(end,b);else{total+=end-start;start=a;end=b;}}return total+(start===null?0:end-start);}
function build(db,filter={}){
 const people=new Map([...(db.archived||[]),...(db.staff||[])].map(s=>[id(s.id),s])),parent=new Map();
 for(const [owner,children]of Object.entries(db.profileLinks||{})){if(!people.has(id(owner)))continue;for(const child of children||[])if(people.has(id(child))&&id(child)!==id(owner))parent.set(id(child),id(owner));}
 const canonical=x=>{let k=id(x),seen=new Set();while(parent.has(k)&&!seen.has(k)){seen.add(k);k=parent.get(k);}return k;};
 const dept=p=>p.department||people.get(id(p.employeeId))?.department||'غير محدد';
 const matches=(p,d)=>d&&(!filter.from||d>=filter.from)&&(!filter.to||d<=filter.to)&&(!filter.employee||canonical(p.employeeId)===canonical(filter.employee))&&(!filter.branch||p.branch===filter.branch)&&(!filter.department||dept(p)===filter.department);
 const groups=new Map(),ensure=(key,fallback)=>{if(!groups.has(key)){const s=people.get(key)||fallback;groups.set(key,{id:key,name:s.name||s.employeeName||'موظف غير محدد',rows:[],opening:[],days:[],departments:new Set(),branches:new Set()});}return groups.get(key);};
 const seen=new Set();for(const p of db.punches||[]){if(!people.has(id(p.employeeId))||!matches(p,day(p.in)))continue;const key=p.id!=null?'id:'+id(p.id):JSON.stringify([p.employeeId,p.in,p.out,p.branch]);if(seen.has(key))continue;seen.add(key);const g=ensure(canonical(p.employeeId),p);g.rows.push({...p,department:dept(p),profileName:people.get(id(p.employeeId))?.name||p.name});g.departments.add(dept(p));g.branches.add(p.branch||'غير محدد');}
 for(const o of db.attendanceOpening||[]){if(!people.has(id(o.employeeId))||!matches(o,o.date))continue;const g=ensure(canonical(o.employeeId),o);g.opening.push(o);g.departments.add(dept(o));g.branches.add(o.branch||'غير محدد');}
 if(filter.employee&&people.has(id(filter.employee)))ensure(canonical(filter.employee),people.get(id(filter.employee)));
 for(const g of groups.values()){g.rows.sort((a,b)=>Date.parse(a.in)-Date.parse(b.in)||id(a.id).localeCompare(id(b.id)));const days=new Map();for(const p of g.rows){const d=day(p.in);if(!days.has(d))days.set(d,[]);days.get(d).push(p);}g.days=[...days].map(([date,rows])=>({date,rows,ms:unionMs(rows)}));g.rawMs=g.rows.reduce((s,p)=>s+duration(p),0);g.ms=unionMs(g.rows);g.overlapMs=g.rawMs-g.ms;g.openingHours=g.opening.reduce((s,o)=>s+(Number.isFinite(Number(o.hours))&&Number(o.hours)>0?Number(o.hours):0),0);g.openCount=g.rows.filter(p=>!p.out).length;g.invalidCount=g.rows.filter(p=>p.out&&!duration(p)).length;}
 const punchIds=new Set([...groups.values()].flatMap(g=>g.rows.map(p=>id(p.id))));const breaks=(db.breaks||[]).filter(b=>punchIds.has(id(b.punchId))).map(b=>({...b})).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start));
 return {breaks,groups:[...groups.values()].sort((a,b)=>a.name.localeCompare(b.name,'ar')),people:[...people.values()].filter(s=>canonical(s.id)===id(s.id)).sort((a,b)=>(a.name||'').localeCompare(b.name||'','ar')),departments:[...new Set([...people.values()].map(s=>s.department).filter(Boolean))].sort(),totalMs:[...groups.values()].reduce((s,g)=>s+g.ms,0),openingHours:[...groups.values()].reduce((s,g)=>s+g.openingHours,0)};
}
function renderPaper(model,filter={},options={}){
 const meta=(label,value)=>`<div><small>${esc(label)}</small><b>${esc(value)}</b></div>`;
 const status=p=>`<span class="ar-status ${!p.out?'ar-open':closeKind(p)==='auto'?'ar-auto':''}">${esc(closeLabel(p))}</span>`;
 const row=p=>`<tr><td data-label="التاريخ">${esc(day(p.in))}</td><td data-label="الحضور">${esc(stamp(p.in))}</td><td data-label="نهاية السجل">${p.out?esc(stamp(p.out)):'مفتوحة'}</td><td data-label="المدة المسجلة">${duration(p)?hours(duration(p)):'—'}</td><td data-label="حالة الإغلاق">${status(p)}${p.out&&!duration(p)?'<small>توقيت غير صالح: يحتاج مراجعة</small>':''}</td><td data-label="الفرع / الملف">${esc(p.branch||'—')}<small>${esc(p.department)} · ${esc(p.profileName)}</small></td></tr>`;
 return `<article id="reportPaper" class="report-paper ar-paper" dir="rtl"><div class="ar-brand"><div><b dir="ltr">ENERGY CLUB</b><h2>تقرير حضور الموظفين</h2><p>Employee attendance report</p></div><div class="ar-issued">صادر: ${esc(stamp(options.generatedAt||new Date().toISOString()))}<br>بتوقيت القاهرة · Africa/Cairo</div></div>${options.synthetic?'<div class="ar-synthetic">بيانات اختبار مصطنعة فقط · SYNTHETIC TEST DATA · ليست سجلات موظفين حقيقية</div>':''}<div class="ar-meta">${meta('الفترة',`${filter.from||'بداية السجلات'} ← ${filter.to||'حتى الآن'}`)}${meta('الفرع',filter.branch||'كل الفروع المتاحة')}${meta('القسم',filter.department||'كل الأقسام المتاحة')}${meta('الموظف',filter.employee?model.groups[0]?.name||'لا يوجد':'كل الموظفين المتاحين')}</div><div class="ar-kpis">${meta('الموظفون في التقرير',model.groups.length)}${meta('الساعات المسجلة دون تداخل',hours(model.totalMs))}${meta('الرصيد الافتتاحي المنفصل',model.openingHours.toFixed(2))}${meta('الورديات المفتوحة',model.groups.reduce((s,g)=>s+g.openCount,0))}</div><p class="ar-note">المدة محسوبة من أوقات السجلات، وليست إثباتًا للحضور الفعلي حتى وقت الإغلاق. الإغلاق التلقائي عند الحد لا يعني انصرافًا مؤكدًا. الورديات المفتوحة لا تدخل الإجمالي. البريك مدفوع ولا يُخصم. اليوم هو تاريخ بداية الوردية بالقاهرة؛ الورديات الليلية تُعرض بتواريخها كاملة.</p>${model.groups.length?model.groups.map(g=>`<section class="ar-employee"><div class="ar-employee-head"><div><h3>${esc(g.name)}</h3><p>${esc([...g.departments].join(' / ')||'لا توجد سجلات')} · ${esc([...g.branches].join(' / '))}</p></div><div><strong>${hours(g.ms)} ساعة</strong><small>${g.days.length} يوم مسجل · ${g.rows.filter(p=>p.out).length} وردية مغلقة · ${g.openCount} مفتوحة</small></div></div>${g.overlapMs>0?`<p class="ar-warning">توجد سجلات متداخلة: مجموع مدد السجلات ${hours(g.rawMs)} ساعة، منها ${hours(g.overlapMs)} ساعة تداخل لم تُحسب مرتين. يلزم مراجعتها؛ لم يتغير أي سجل.</p>`:''}<table class="ar-table"><thead><tr class="ar-repeat-name"><th colspan="6">${esc(g.name)} · ${options.synthetic?'بيانات اختبار مصطنعة · ':''}أيام الحضور مرتبة حسب تاريخ البداية بالقاهرة</th></tr><tr><th>التاريخ</th><th>الحضور</th><th>نهاية السجل</th><th>المدة (ساعة)</th><th>حالة الإغلاق</th><th>الفرع / الملف</th></tr></thead><tbody>${g.days.map(d=>d.rows.map(row).join('')+(d.rows.length>1?`<tr class="ar-day-total"><td colspan="3">إجمالي يوم ${esc(d.date)} دون تداخل</td><td>${hours(d.ms)}</td><td colspan="2">${d.rows.length} وردية</td></tr>`:'')).join('')||'<tr><td colspan="6">لا توجد ورديات في الفترة المختارة</td></tr>'}</tbody><tfoot><tr><td colspan="3">إجمالي ${esc(g.name)} دون تداخل</td><td>${hours(g.ms)}</td><td colspan="2">الرصيد الافتتاحي: ${g.openingHours.toFixed(2)} ساعة (منفصل)</td></tr></tfoot></table>${g.opening.length?`<div class="ar-opening"><b>رصيد افتتاحي إداري، ليس بصمات حضور</b>${g.opening.map(o=>`<p>${esc(o.date)} · ${Number(o.hours||0).toFixed(2)} ساعة · ${esc(o.reason||'بلا سبب مسجل')}</p>`).join('')}</div>`:''}</section>`).join(''):'<p class="ar-empty">لا توجد سجلات تطابق الاختيار. راجع الفترة والموظف والقسم والفرع.</p>'}${model.breaks?.length?`<details class="ar-breaks"><summary>تفاصيل البريكات المسجلة (${model.breaks.length}) · مدفوعة ولا تُخصم من الساعات</summary><table class="ar-table"><thead><tr><th>الموظف</th><th>بداية البريك</th><th>النهاية</th><th>المدة (دقيقة)</th></tr></thead><tbody>${model.breaks.map(b=>`<tr><td data-label="الموظف">${esc(b.name||'—')}</td><td data-label="البداية">${esc(stamp(b.start))}</td><td data-label="النهاية">${b.end?esc(stamp(b.end)):'مفتوح'}</td><td data-label="المدة">${b.end&&Date.parse(b.end)>=Date.parse(b.start)?((Date.parse(b.end)-Date.parse(b.start))/60000).toFixed(0):'—'}</td></tr>`).join('')}</tbody></table></details>`:''}<div class="ar-footer"><span>Energy Club · تقرير إداري من السجلات المتاحة لحسابك</span><span>إجمالي الساعات ليس اعتمادًا لصرف المرتبات</span></div></article>`;
}
function csv(model){const safe=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,' $&').replace(/"/g,'""')+'"';const rows=[['الموظف','القسم','الفرع','اليوم بالقاهرة','الحضور بالقاهرة','نهاية السجل بالقاهرة','المدة المسجلة بالساعة','مصدر الإغلاق','نوع السطر']];for(const g of model.groups){for(const p of g.rows)rows.push([g.name,p.department,p.branch,day(p.in),stamp(p.in),p.out?stamp(p.out):'مفتوحة',duration(p)?hours(duration(p)):'',closeLabel(p),'وردية']);rows.push([g.name,'','','','','',hours(g.ms),'دون تداخل، دون رصيد افتتاحي','إجمالي الموظف']);for(const o of g.opening)rows.push([g.name,'',o.branch,o.date,'','',Number(o.hours||0).toFixed(2),'رصيد افتتاحي إداري','رصيد افتتاحي منفصل']);}return '\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n');}
const api={build,renderPaper,csv,day,stamp,duration,unionMs,closeLabel,closeKind};root.EnergyAttendanceReport=api;if(typeof module!=='undefined')module.exports=api;
if(typeof window==='undefined'||typeof render==='undefined')return;
window.addEventListener('afterprint',()=>document.querySelectorAll('.ar-breaks').forEach(d=>{d.open=d.dataset.wasOpen==='1';}));
const previous=render;let filter={from:'',to:'',employee:'',branch:'',department:''};
render=function(){previous();if(page!=='reports'||!document.getElementById('reportPaper'))return;const model=build(db,filter),sel=(name,items,all)=>`<select name="${name}"><option value="">${all}</option>${items.map(([value,label])=>`<option value="${esc(value)}" ${id(filter[name])===id(value)?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
const container=document.getElementById('reportPaper').parentElement;container.innerHTML=`<form id="arFilters" class="ar-filters no-print"><label>من<input name="from" type="date" value="${esc(filter.from)}"></label><label>إلى<input name="to" type="date" value="${esc(filter.to)}"></label><label>الموظف${sel('employee',model.people.map(s=>[s.id,s.name]),'كل الموظفين')}</label><label>القسم${sel('department',model.departments.map(s=>[s,s]),'كل الأقسام')}</label><label>الفرع${sel('branch',(db.branches||[]).map(b=>[b.name,b.name]),'كل الفروع')}</label><button class="primary">عرض التقرير</button><button type="button" id="arReset">مسح الاختيارات</button></form>${renderPaper(model,filter)}<div class="ar-actions no-print"><button class="primary" id="arPrint">طباعة / حفظ PDF</button><button id="arCSV">تصدير CSV</button></div>`;
document.getElementById('arFilters').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),next=Object.fromEntries(f);if(next.from&&next.to&&next.from>next.to){toast('تاريخ البداية لازم يسبق النهاية');return;}filter=next;render();};document.getElementById('arReset').onclick=()=>{filter={from:'',to:'',employee:'',branch:'',department:''};render();};document.getElementById('arPrint').onclick=()=>{document.querySelectorAll('.ar-breaks').forEach(d=>{d.dataset.wasOpen=d.open?'1':'0';d.open=true;});document.body.classList.add('printing-report');window.print();};document.getElementById('arCSV').onclick=()=>{const u=URL.createObjectURL(new Blob([csv(model)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='Energy-Club-Attendance.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};};
})(typeof window!=='undefined'?window:globalThis);
